export type OrderStatus = 'placed' | 'confirmed' | 'prepping' | 'quality_check' | 'out_for_delivery' | 'delivered' | 'cancelled';

export interface Order {
  id: string;
  customerId: string;
  items: any[]; // To keep it flexible for now
  total: number;
  status: OrderStatus;
  date: string;
  paymentMethod: string;
  shippingAddress?: string;
}



export const orders: Order[] = [
  {
    id: "ORD-001",
    customerId: "1",
    items: [{ name: "Full Goat", quantity: 1, price: 35000 }],
    total: 35000,
    status: "delivered",

    date: "2024-03-10",
    paymentMethod: "Paystack",
  },
  {
    id: "ORD-002",
    customerId: "2",
    items: [{ name: "Sheep Whole", quantity: 1, price: 45000 }],
    total: 45000,
    status: "prepping",

    date: "2024-03-12",
    paymentMethod: "Transfer",
  },
];

export const getOrders = async (): Promise<Order[]> => {
  return orders;
};

export const getOrderById = async (id: string): Promise<Order | undefined> => {
  return orders.find(o => o.id === id);
};

export const getOrdersByCustomerId = async (customerId: string): Promise<Order[]> => {
  return orders.filter(o => o.customerId === customerId);
};
